/* *  vlen.h * *  structure used for passing vlen paramaters back and forth */struct vDetail {        int minRec;                /* smallest record length allowed       */        int maxRec;                /* largest record allowed               */        long count;                /* number of records in mapper          */        long mDel;                 /* number of deleted mapper entries     */        long stDel;                /* number of deleted bytes in the store */        long stLast;               /* last byte in use in the store        */    };/* *  that's all, folks! */